<div class="d-flex justify-content-between mb-3"><h4>Purchase Returns</h4><?php if (Auth::can('inventory.purchasing.create')): ?><a class="btn btn-primary" href="<?= url('purchasing/return_form') ?>"><i class="bi bi-plus-lg"></i> New return</a><?php endif; ?></div>
<div class="card"><div class="table-responsive"><table class="table table-sm mb-0 align-middle"><thead class="table-light"><tr><th>No</th><th>Date</th><th>Supplier</th><th>Reason</th><th class="text-end">Credit</th><th>Status</th><th></th></tr></thead><tbody>
<?php foreach ($rows as $r): ?><tr><td><?= e($r['pr_no']) ?></td><td><?= e(fmt_date($r['created_at'])) ?></td><td><?= link_supplier($r['supplier_id'], $r['supplier']) ?></td><td><?= e($r['reason']) ?></td><td class="text-end"><?= number_format($r['total'], 2) ?></td><td><?= badge($r['status']) ?></td>
<td class="text-nowrap"><?php if ($r['status'] === 'pending' && Auth::can('inventory.purchasing.approve')): foreach (['approved' => ['success', 'check-lg'], 'rejected' => ['danger', 'x-lg']] as $d => [$c, $i]): ?><form method="post" action="<?= url('purchasing/return_decide') ?>" class="d-inline"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="decision" value="<?= $d ?>"><button class="btn btn-sm btn-outline-<?= $c ?>"><i class="bi bi-<?= $i ?>"></i></button></form><?php endforeach; endif; ?></td></tr><?php endforeach; ?>
<?php if (!$rows): ?><tr><td colspan="7" class="text-center text-muted py-3">None.</td></tr><?php endif; ?></tbody></table></div></div>
